// quotation_resources_search.js — generated by Generate Module

$(document).ready(function () {

  // ── Quotation picker ─────────────────────────────────────────────────────
  const quotationPicker = $('#qrQuotationPickerTable').DataTable({
    ajax: { url: '/modules/operations/quotations/quotation_entries/quotation_entries_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'm_customers.customer_name', defaultContent: '' },
      { data: 'quotation_date', defaultContent: '' },
      { data: 'total_amount', defaultContent: '' },
    ],
    pageLength: 10,
    searching: true,
    dom: '<"d-flex justify-content-between align-items-center mb-2"f>rtip',
    language: { search: 'Filter:', info: 'Showing _START_ to _END_ of _TOTAL_' },
  });

  $('#qrQuotationPickerTable tbody').on('click', 'tr', function () {
    const data = quotationPicker.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('qrQuotationPickerModal')).hide();
    document.dispatchEvent(new CustomEvent('qr-quotation-selected', { detail: data }));
  });

  $('#qrQuotationPickerModal').on('shown.bs.modal', function () {
    quotationPicker.ajax.reload(null, false);
    quotationPicker.columns.adjust();
  });

  // ── Vehicle Type picker ──────────────────────────────────────────────────
  const vehicleTypePicker = $('#qrVehicleTypePickerTable').DataTable({
    ajax: { url: '/modules/master_files/vehicle/vehicle_type/vehicle_type_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'code' },
      { data: 'name' },
    ],
    pageLength: 10,
    searching: true,
    dom: '<"d-flex justify-content-between align-items-center mb-2"f>rtip',
    language: { search: 'Filter:', info: 'Showing _START_ to _END_ of _TOTAL_' },
  });

  $('#qrVehicleTypePickerTable tbody').on('click', 'tr', function () {
    const data = vehicleTypePicker.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('qrVehicleTypePickerModal')).hide();
    document.dispatchEvent(new CustomEvent('qr-vehicle-type-selected', { detail: data }));
  });

  $('#qrVehicleTypePickerModal').on('shown.bs.modal', function () {
    vehicleTypePicker.ajax.reload(null, false);
    vehicleTypePicker.columns.adjust();
  });

  const table = $('#quotationResourcesSearchTable').DataTable({
    ajax: { url: '/modules/operations/quotations/quotation_resources/quotation_resources_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'm_quotations.ref', defaultContent: '' },
      { data: 'm_vehicle_types.name', defaultContent: '' },
      { data: 'quantity' },
      { data: 'remarks' },
    ],
    pageLength: 10,
    lengthMenu: [5, 10, 25, 50],
    dom: '<"d-flex justify-content-between align-items-center mb-2"Bf>rtip',
    buttons: [
      { extend: 'copy',  className: 'btn btn-sm btn-secondary' },
      { extend: 'excel', className: 'btn btn-sm btn-success',  text: '<i class="bi bi-file-earmark-excel me-1"></i>Excel' },
      { extend: 'csv',   className: 'btn btn-sm btn-info',     text: '<i class="bi bi-filetype-csv me-1"></i>CSV' },
      { extend: 'pdf',   className: 'btn btn-sm btn-danger',   text: '<i class="bi bi-file-earmark-pdf me-1"></i>PDF' },
      { extend: 'print', className: 'btn btn-sm btn-secondary' },
    ],
    language: {
      search: 'Global search:',
      lengthMenu: 'Show _MENU_ entries',
      info: 'Showing _START_ to _END_ of _TOTAL_ Quotation Resources records',
    },
  });

  $('#quotationResourcesSearchTable tbody').on('click', 'tr', function () {
    const data = table.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('quotationResourcesSearchModal')).hide();
    document.dispatchEvent(new CustomEvent('quotation_resources-selected', { detail: data }));
  });

  $('#quotationResourcesSearchModal').on('shown.bs.modal', function () {
    table.ajax.reload(null, false);
    table.columns.adjust();
  });

});
